    [Theory]
    [MemberData(nameof(Destinations))]
    public async Task NavigationRevalidatesDestinationsAndPreservesAttemptState(
        bool prepared, string name, string script, int status, string outputHex, string diagnostic,
        string mutation, string target, string boundary, string currentDirectory, string queries, string filesJson)
    {
        var memory = new MemoryGovernor(1024 * 1024);
        using var owner = memory.CreateScope();
        await using var host = new TestHost { MemoryBudget = owner };
        foreach (var directory in new[] { "/a", "/b", "/c" }) host.AddDirectory(directory);
        var requests = new List<string>();
        var boundaryReached = false;
        host.BeforeGetPathInfo = path => requests.Add(path.Path);
        host.AfterGetPathInfo = async (path, request) =>
        {
            Assert.Equal(FilePathInfoRequest.KindOnly, request);
            if (path.Path != boundary || boundaryReached) return;
            boundaryReached = true;
            if (mutation == "file") host.AddFile(target, "replaced");
            else if (mutation == "missing")
                Assert.Null(await host.DeleteDirectoryAsync(new FileEntryPath(new ShellPath(target)), CancellationToken.None));
        };
        using var cancel = new CancellationTokenSource(TimeSpan.FromSeconds(10));
        var result = prepared
            ? await new Engine().RunAsync(new Eval(Parser.Parse(script)), host, owner, cancel.Token)
            : await BashScript.RunAsync(host, script, EvaluationOptions.Default, cancel.Token);

        Assert.Equal(status, result.ExitCode);
        Assert.Equal(currentDirectory, result.CurrentDirectory.Path);
        Assert.Equal(Convert.FromHexString(outputHex), host.StandardOutput.Content.ToArray());
        Assert.Equal(diagnostic, host.StandardError.TextContent);
        Assert.Equal(queries.Length == 0 ? [] : queries.Split('|'), requests);
        Assert.Equal(!name.StartsWith("empty-", StringComparison.Ordinal), boundaryReached);
        var files = JsonSerializer.Deserialize<SortedDictionary<string, string>>(filesJson)
            ?? throw new InvalidDataException();
        Assert.Equal(files.ToArray(), host.CaptureEntries()
            .Select(p => new KeyValuePair<string, string>(p.Key, p.Value.Kind + ":" + p.Value.ContentHex)).ToArray());
        Assert.Equal(0, host.OpenFileCount);
        owner.Dispose();
        Assert.Equal(0, memory.ReservedBytes);
    }
}
